// pages/Home.js
import React from "react";
import { Link } from "react-router-dom";

function Home() {
  return (
    <div style={{ textAlign: "center", padding: "80px 20px" }}>
      <h1 style={{ fontSize: 32, marginBottom: 12 }}>Welcome to Apple</h1>
      <p style={{ color: "#6e6e73", marginBottom: 24 }}>
        Check out the latest iPhone lineup.
      </p>
      <Link
        to="/iphone"
        style={{
          background: "#0071e3",
          color: "#fff",
          padding: "10px 24px",
          borderRadius: 20,
          textDecoration: "none",
          fontSize: 15,
        }}
      >
        Shop iPhone &gt;
      </Link>
    </div>
  );
}

export default Home;
